import { readFile, writeFile } from 'node:fs/promises';

// Generated data module lets browser and Node renderers produce the same offline artifact.
const bindings = await readFile(new URL('../src/wasm/constellation_core.js', import.meta.url), 'utf8');
const bytes = await readFile(new URL('../src/wasm/constellation_core_bg.wasm', import.meta.url));
await writeFile(new URL('../src/wasm/inline.mjs', import.meta.url),
  '// Generated by scripts/build-inline-wasm.mjs; do not edit.\n' +
  `export const bindings = ${JSON.stringify(bindings)};\nexport const base64 = ${JSON.stringify(bytes.toString('base64'))};\n`);
